use vb_core::{
    CompiledInputSlot, CompiledNodeKind, CompiledWorkflow, WorkflowParts,
    SlotIdx, InputSlotKind, SlotValue, Taint, RunId,
};
use vb_compile::{compile_source, parse_workflow_source};
use vb_engine::{EngineSignal, StepBudget, new_run_frame, run_until_blocked};
use vb_value_store::ValueStore;

fn compile(yaml: &str) -> Result<CompiledWorkflow, Box<dyn std::error::Error>> {
    Ok(compile_source(&parse_workflow_source(yaml)?)?)
}

fn run(workflow: &CompiledWorkflow, values: &[i64]) -> Result<EngineSignal, Box<dyn std::error::Error>> {
    let mut frame = new_run_frame(RunId::new(1), workflow)?;
    for (port, value) in workflow.input_slots().iter().zip(values.iter()) {
        frame.write_slot_with_taint(port.slot, SlotValue::I64(*value), Taint::Secret)?;
    }
    Ok(run_until_blocked(workflow, &mut frame, StepBudget::MAX, &mut ValueStore::new())?)
}

const BASE: &str = "version: velvet-ballistics/v1\nname: input_finish\nwhen:\n  manual: {}\ninputs:\n  count: number\nsteps:\n  - id: done\n    finish:\n      result: $input.count\n";

#[test]
fn test_compile_base() -> Result<(), Box<dyn std::error::Error>> {
    let workflow = compile(BASE)?;
    assert_eq!(workflow.input_slots(), &[CompiledInputSlot { slot: SlotIdx::new(0), kind: InputSlotKind::I64 }]);
    for value in [i64::MIN, -1, 0, 42, i64::MAX] {
        let signal = run(&workflow, &[value])?;
        assert_eq!(signal, EngineSignal::Finished(SlotValue::I64(value), Taint::Secret));
    }
    Ok(())
}

